.hero{width:min(1120px,calc(100% - 34px));margin:18px auto 0;display:grid;grid-template-columns:.92fr 1.08fr;align-items:center;min-height:570px}.hero-copy{position:relative;z-index:2;padding:60px 0 70px}.eyebrow{color:var(--gold);font-family:'Trebuchet MS',sans-serif;font-weight:800;letter-spacing:.18em;text-transform:uppercase;font-size:.74rem}h1{font-size:clamp(3.45rem,8vw,7.6rem);line-height:.8;letter-spacing:-.065em;font-weight:500;margin:26px 0 30px;max-width:760px}h1 span{color:var(--red);display:block;font-style:italic}.lede{max-width:520px;font-size:clamp(1.05rem,2vw,1.32rem);line-height:1.62;color:#dacfb9}.begin{display:inline-flex;align-items:center;gap:14px;margin-top:28px;background:var(--gold);color:var(--ink);padding:15px 19px;text-decoration:none;font-family:'Trebuchet MS',sans-serif;font-weight:900;text-transform:uppercase;letter-spacing:.08em;box-shadow:7px 7px 0 var(--red)}.hero-art{position:relative;margin-left:-74px;transform:rotate(2deg)}.hero-art:before{content:'';position:absolute;inset:17px -17px -17px 17px;border:2px solid var(--gold);z-index:-1}.hero-art img{width:100%;display:block;filter:saturate(.92) contrast(1.05);clip-path:polygon(4% 2%,100% 0,96% 97%,0 100%)}.caption{position:absolute;bottom:-38px;right:8px;color:var(--muted);font:.72rem 'Trebuchet MS',sans-serif;letter-spacing:.1em;text-transform:uppercase}
.bench{background:var(--paper);color:var(--ink);padding:90px 0 100px;position:relative}.bench:before{content:'';position:absolute;top:0;left:0;right:0;height:12px;background:repeating-linear-gradient(90deg,var(--red) 0 34px,var(--ink) 34px 68px,var(--gold) 68px 102px)}.worktop{width:min(920px,calc(100% - 34px));margin:auto}.lesson-head{display:grid;grid-template-columns:1fr auto;gap:30px;align-items:end;border-bottom:3px solid var(--ink);padding-bottom:24px}.kicker{font:800 .72rem 'Trebuchet MS',sans-serif;text-transform:uppercase;letter-spacing:.18em;color:var(--red)}h2{margin:8px 0 0;font-size:clamp(2.15rem,5vw,4rem);line-height:.95;font-weight:500;letter-spacing:-.04em}.round-count{font:900 1rem 'Trebuchet MS',sans-serif;text-transform:uppercase}.gauges{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:27px 0 42px}.gauge{background:var(--ink);color:var(--paper);padding:12px 14px}.gauge-label{display:flex;justify-content:space-between;font:800 .68rem 'Trebuchet MS',sans-serif;letter-spacing:.1em;text-transform:uppercase;margin-bottom:8px}.track{height:7px;background:rgba(255,255,255,.15);overflow:hidden}.fill{height:100%;width:50%;background:var(--teal);transition:width .65s cubic-bezier(.2,.8,.2,1)}#heatFill{background:var(--red);width:20%}#clarityFill{background:var(--gold)}
.comment-card{position:relative;background:var(--cream);border:2px solid var(--ink);padding:28px 28px 28px 74px;box-shadow:9px 9px 0 var(--teal)}.avatar{position:absolute;left:18px;top:24px;width:40px;height:40px;display:grid;place-items:center;background:var(--red);color:#fff;border-radius:50%;font:900 1.1rem 'Trebuchet MS',sans-serif}.handle{font:800 .72rem 'Trebuchet MS',sans-serif;letter-spacing:.12em;text-transform:uppercase;color:var(--teal);margin-bottom:9px}#comment{font-size:clamp(1.1rem,2.4vw,1.42rem);line-height:1.45;margin:0}.instruction{margin:40px 0 15px;font:900 .75rem 'Trebuchet MS',sans-serif;letter-spacing:.16em;text-transform:uppercase}.choices{display:grid;gap:12px}.choice{width:100%;text-align:left;border:2px solid var(--ink);background:transparent;color:var(--ink);padding:17px 19px;cursor:pointer;display:grid;grid-template-columns:34px 1fr;gap:10px;align-items:start;line-height:1.4;transition:transform .15s,background .15s,color .15s}.choice:hover:not(:disabled){transform:translateX(6px);background:var(--ink);color:var(--paper)}.choice:disabled{cursor:default}.choice.good{background:var(--teal);color:#fff;border-color:var(--teal)}.choice.missed{border-color:var(--red);text-decoration:line-through;opacity:.65}.letter{font:900 .75rem 'Trebuchet MS',sans-serif;width:25px;height:25px;border:1px solid currentColor;border-radius:50%;display:grid;place-items:center}.feedback{display:none;margin-top:22px;border-left:7px solid var(--gold);background:rgba(217,165,47,.15);padding:18px 20px;line-height:1.5}.feedback.show{display:block;animation:rise .35s ease both}.feedback strong{display:block;font:900 .75rem 'Trebuchet MS',sans-serif;text-transform:uppercase;letter-spacing:.13em;margin-bottom:6px}.next{display:none;margin:22px 0 0 auto;border:0;background:var(--red);color:#fff;padding:14px 18px;cursor:pointer;font:900 .76rem 'Trebuchet MS',sans-serif;text-transform:uppercase;letter-spacing:.12em}.next.show{display:block}
.result{display:none;text-align:center;padding:35px 0 5px}.result.show{display:block;animation:rise .5s ease both}.seal{width:130px;aspect-ratio:1;margin:0 auto 25px;border-radius:50%;display:grid;place-items:center;border:5px double var(--paper);outline:7px solid var(--red);background:var(--red);color:#fff;transform:rotate(-5deg);font:900 .75rem 'Trebuchet MS',sans-serif;letter-spacing:.1em;text-transform:uppercase}.result h2{font-size:clamp(2.8rem,8vw,5.8rem)}.result p{max-width:570px;margin:20px auto;font-size:1.18rem;line-height:1.55}.restart{border:2px solid var(--ink);background:transparent;padding:13px 18px;font:900 .75rem 'Trebuchet MS',sans-serif;text-transform:uppercase;cursor:pointer}
.field-guide{width:min(1120px,calc(100% - 34px));margin:auto;padding:95px 0}.guide-grid{display:grid;grid-template-columns:.65fr 1.35fr;gap:70px}.field-guide h2{color:var(--paper)}.intro-note{color:var(--muted);font-size:1.08rem;line-height:1.6}.tools{display:grid;grid-template-columns:repeat(2,1fr);border-top:1px solid var(--line);border-left:1px solid var(--line)}.tool{min-height:180px;padding:25px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}.tool b{display:block;color:var(--gold);font:900 .73rem 'Trebuchet MS',sans-serif;letter-spacing:.14em;text-transform:uppercase;margin-bottom:13px}.tool p{color:#d6ccb8;line-height:1.5;margin:0}footer{border-top:1px solid var(--line);padding:27px 17px 50px;text-align:center;color:var(--muted);line-height:1.6}footer a{color:var(--paper);text-decoration-color:var(--red);text-underline-offset:4px}@keyframes rise{from{opacity:0;transform:translateY(12px)}}
@media(max-width:760px){.hero{display:block;min-height:0;margin-top:0}.hero-copy{padding:48px 0 18px}h1{font-size:clamp(3.55rem,18vw,5.5rem)}.hero-art{margin:20px 0 80px;transform:rotate(1deg)}.lesson-head{display:block}.round-count{margin-top:18px}.gauges{grid-template-columns:1fr}.guide-grid{grid-template-columns:1fr;gap:38px}.tools{grid-template-columns:1fr}.comment-card{padding:72px 20px 23px}.avatar{top:18px}.handle{position:absolute;top:29px;left:70px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;animation:none!important;transition:none!important}}
</style></head><body>
